"use strict";(globalThis.webpackChunkwegent_docs=globalThis.webpackChunkwegent_docs||[]).push([[132],{13432:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"wegent/developer-guide/wework-stand-in","title":"Wework Stand-in","description":"The Chinese UI calls this feature \u201c\u5206\u8eab\u201d (My Stand-in: \u201c\u6211\u7684\u5206\u8eab\u201d); English labels and internal stand-in identifiers remain unchanged. Stand-ins belong to the person. The collaboration navigation lists existing personal stand-ins by name, enablement and connected projects, even before their first execution. Clicking a stand-in opens its settings. Unnamed stand-ins use Default stand-in with an index when needed; connected project names never become implicit stand-in names. Actual execution history appears below, grouped by project. History rows open their Runtime tasks. Configuration is a secondary Settings page. A single stand-in is the default; a picker appears only when there are several. The UI consistently calls them stand-ins; the stored roles array is their configuration list, not another user-facing role layer.","source":"@site/docs/wegent/developer-guide/wework-stand-in.md","sourceDirName":"wegent/developer-guide","slug":"/wegent/developer-guide/wework-stand-in","permalink":"/wegent-docs/docs/wegent/developer-guide/wework-stand-in","draft":false,"unlisted":false,"editUrl":"https://github.com/wecode-ai/wegent-docs/edit/main/docs/wegent/developer-guide/wework-stand-in.md","tags":[],"version":"current","sidebarPosition":42,"frontMatter":{"sidebar_position":42},"sidebar":"wegentSidebar","previous":{"title":"Project member settings","permalink":"/wegent-docs/docs/wegent/developer-guide/project-member-settings"},"next":{"title":"Runtime conversation consistency","permalink":"/wegent-docs/docs/wegent/developer-guide/runtime-conversation-consistency"}}');var s=t(74848),a=t(28453);const o={sidebar_position:42},r="Wework Stand-in",c={},d=[{value:"Role selection",id:"role-selection",level:2},{value:"Feedback in collaboration notifications",id:"feedback-in-collaboration-notifications",level:2},{value:"Verification",id:"verification",level:2}];function l(e){const n={code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"wework-stand-in",children:"Wework Stand-in"})}),"\n",(0,s.jsxs)(n.p,{children:["The Chinese UI calls this feature \u201c\u5206\u8eab\u201d (My Stand-in: \u201c\u6211\u7684\u5206\u8eab\u201d); English labels and internal ",(0,s.jsx)(n.code,{children:"stand-in"})," identifiers remain unchanged. Stand-ins belong to the person. The collaboration navigation lists existing personal stand-ins by name, enablement and connected projects, even before their first execution. Clicking a stand-in opens its settings. Unnamed stand-ins use Default stand-in with an index when needed; connected project names never become implicit stand-in names. Actual execution history appears below, grouped by project. History rows open their Runtime tasks. Configuration is a secondary Settings page. A single stand-in is the default; a picker appears only when there are several. The UI consistently calls them stand-ins; the stored ",(0,s.jsx)(n.code,{children:"roles"})," array is their configuration list, not another user-facing role layer."]}),"\n",(0,s.jsx)(n.p,{children:"The project toolbar opens Project stand-in. It selects an already connected stand-in first, otherwise the first eligible personal stand-in. Existing instructions, agent and automatic-handling status are shown read-only. For an enabled project, the primary action is exclusively Disable for this project. Saving disconnects every matching stand-in from this project, using exclusions for all-project sources and disabling the collaboration source of project-bound agents. Global enablement, other projects and existing executions remain unchanged. For a disabled project, the primary action is exclusively Enable and use for this project, enabling the selected stand-in and connecting the project. The UI explains that enablement also applies to its other connected projects and only new assignments after enablement are handled. Agent selection and instructions remain unchanged. A separate link explicitly opens personal settings and explains their cross-project effect. Save or Cancel returns to the original project, preserving an explicitly saved execution device. A first connection enables only the current project rather than all projects. Selection-error recovery is available only in personal settings; retry stays in the editor without adding project connections."}),"\n",(0,s.jsx)(n.p,{children:"Create a stand-in for this project creates a personally owned stand-in with the project name and a single-project connection, also visible in personal settings. Instructions are expanded; execution settings are collapsed. Secondary views stay scoped to the selected stand-in without another picker. Choosing a project agent connects its owning project and limits the stand-in to it. While signed out, no cloud personal-agent catalog is requested and no login or load-failure hint is shown; the general assistant and eligible project agents remain available. Genuine catalog failures retain an explicit retry action."}),"\n",(0,s.jsx)(n.p,{children:"Instructions reuse the normal composer, skills, plugins and Goal mode. Device, model and code workspace live under More settings. Saving does not depend on cloud catalogs, project device bindings or model readiness; dispatch validates the current actor, Issue permission and the agent's device and model policies."}),"\n",(0,s.jsx)(n.p,{children:"Every edit, including the automatic handling toggle, takes effect only after Save. Prompt and execution changes merge into the current role through functional updates, so delayed composer callbacks cannot overwrite newer toggle, device or workspace values. Failed saves retain the draft; version conflicts cannot overwrite another editor. Closing a dirty configuration requires explicit discard. Back from a secondary page discards that page's edits. Disabling stops new assignments while existing Runtime tasks continue."}),"\n",(0,s.jsx)(n.p,{children:"A role can cover all participating collaboration projects, including future projects, with individual exclusions, or a selected project list. Optional tags narrow its scope. Settings are account-scoped in the selected Executor's SQLite database; devices remain independent. Settings belong to the Executor that stores them. After a desktop device identity change, reads and scheduling bind the document and its stand-ins to the current Executor, preserving instructions, scopes, versions and assignment cutoffs. Saves still reject settings addressed to another device. The frontend passes the selected Executor explicitly as the request target, without deriving routing from stored device fields, duplicating local-device or project-access validation, or rewriting device ownership in responses. The Executor validates ownership and permissions. Local projects are displayed only on their owning device."}),"\n",(0,s.jsx)(n.p,{children:"One personal document owns role configuration, ordering, versions and the shared automatic-selection option. Legacy project configurations migrate transactionally into roles preserving project scopes, assignment cutoffs and original project-agent authority. Project-addressed RPCs are projections over this document, with no duplicate project persistence."}),"\n",(0,s.jsx)(n.h2,{id:"role-selection",children:"Role selection"}),"\n",(0,s.jsx)(n.p,{children:"Scope and exact tag matching are deterministic. Tagged matches take precedence over unrestricted roles. A single matching role executes directly. Multiple matches use the first role in the shared scheduling order by default, with exactly one execution per assignment."}),"\n",(0,s.jsx)(n.p,{children:"The shared checkbox enables model selection only when several roles match. Selection consumes tokens; notification ingestion, deduplication and rule matching do not. A restricted ephemeral request without tools returns one allowed role ID and a reason. Decisions are cached by assignment and configuration version, including failures, to avoid repeated model calls. Selection failures appear in personal settings and can be retried after adjusting settings or clicking Retry. A failed selection does not block other assignments in the same project."}),"\n",(0,s.jsx)(n.p,{children:"Cloud projects reuse assignment notifications already received by Wework instead of scanning projects or polling assignments every five seconds. The desktop notification entry uses the loaded inbox and online device list, deduplicates by account, device and notification, and calls the existing Runtime RPC on each relevant device. Each device checks enabled personal settings, the current user, project, assignment identity and tags before validating assignment status and the enable-time cutoff. Each dispatch reads assignments only once. Local projects retain scheduling against local storage without cloud project or assignment requests. Historical, unrelated, unassigned and already-bound work is excluded before ordinary task creation, binding, sessions and result views are reused. Reloading the desktop reprocesses the loaded inbox while existing Runtime tasks are reused without another assignments request or execution. Automatic handling requires receipt of an assignment notification; failures are logged instead of retrying on every inbox refresh. Before task creation, the original notification still offers Delegate for explicit manual recovery; an existing failed task retains Retry. Explicit settings saves and role-selection retries reconsider loaded notifications for the updated device. Manual delegation works with automatic handling disabled and uses the same selection policy when no role is specified. Execution provenance records the selected role and reason. Cloud execution retains current Issue permission checks; local work remains functional offline. No new backend queue or distributed lock is introduced."}),"\n",(0,s.jsx)(n.h2,{id:"feedback-in-collaboration-notifications",children:"Feedback in collaboration notifications"}),"\n",(0,s.jsx)(n.p,{children:"Collaboration notifications read the existing Runtime execution list and match stand-in tasks by project, Issue, and assignment identity. The stand-in icon defaults to 28px, with a 16px project-sidebar variant. The primary person and double reuse identical outlines, with a slightly smaller primary person. When disabled, the double tucks into a thick shadow along the person\u2019s right side. Enabling unfolds it toward the upper right over about 560ms. The double has no violet coloring, hatching or facial features. Disabling reverses the movement into the thick right-hand shadow. A project-sidebar icon appears only while the current user has at least one enabled stand-in for that project. Projects without an enabled stand-in have no icon; disabling every matching stand-in removes it without affecting other projects. Reduced-motion mode displays the final state immediately. Cropped lower bodies emphasize the two heads and shadow identity. Colors invert with the theme on dark backgrounds. The original assignment notification shows the stand-in icon and working, waiting, finished, or failed state. Local and manually started stand-ins without an assignment notification also appear here. Clicking the task title opens the existing execution conversation without dispatching another task."}),"\n",(0,s.jsx)(n.p,{children:"Notifications show the source, event and time, task content, and lightweight actions without an extra \u201cNew task\u201d heading. New notifications snapshot the actual assigning user or manager agent name at creation; inbox reads do not query related records. Entries without a name omit assigner information and show the task title and time directly, without placeholder copy. Stand-in handling updates the identity and state in the same entry."}),"\n",(0,s.jsx)(n.p,{children:"The inline handling area accepts follow-up instructions, answers real Runtime questions, and retries failed stand-in tasks. Ordinary follow-up input expands after clicking Reply; pending questions appear directly. Replies continue the same conversation. A rejected send keeps the draft and displays the error. Question options and request identifiers come from the conversation, never from interpreting result text."}),"\n",(0,s.jsx)(n.p,{children:"Completion, failure, and pending input make the entry unread again and update its position. Desktop alerts respect collaboration notification preferences and are suppressed while that execution is visible. The desktop frontend owns this projection; no backend API or Executor protocol is added."}),"\n",(0,s.jsx)(n.p,{children:"Stand-in read markers and desktop delivery receipts are account-scoped on the current device and do not sync between devices. Original assignment notifications retain the existing read API. Each auxiliary collection retains at most 1000 entries for 90 days and is pruned on reads and writes. Cleanup never deletes real notifications, tasks, or execution history."}),"\n",(0,s.jsx)(n.p,{children:"Completion events use the Runtime turn ID when available; tasks without a turn ID retain their existing status-and-timestamp identity. With a turn ID, receiving a turn settlement and its task summary separately does not repeat an alert or make an already-read result unread. Existing timestamp markers are upgraded when they match the current state. Restored settlements from before account monitoring began establish a delivery baseline and retain their inbox entries and unread state without replaying historical desktop alerts. Tasks that finish after monitoring starts still notify, including tasks that finish before their first summary is discovered."}),"\n",(0,s.jsxs)(n.p,{children:["Focused tests cover durable versioned settings, independent tag rules, assignment age, existing binding filtering, device switching, and sidebar configuration merging and updates. The ",(0,s.jsx)(n.code,{children:"stand-in-assignment-notifications"}),", ",(0,s.jsx)(n.code,{children:"stand-in"}),", ",(0,s.jsx)(n.code,{children:"stand-in-workspace"}),", ",(0,s.jsx)(n.code,{children:"stand-in-cloud"}),", ",(0,s.jsx)(n.code,{children:"stand-in-controls"}),", and ",(0,s.jsx)(n.code,{children:"stand-in-notifications"})," desktop checkpoints run in existing CI. Only model responses are replaced; storage, task execution, cloud APIs, and device connections use real implementations."]}),"\n",(0,s.jsx)(n.h2,{id:"verification",children:"Verification"}),"\n",(0,s.jsx)(n.p,{children:"Use isolated Electron, project and Executor fixtures; cloud checkpoints use real backend APIs and connections. Only model responses are substituted. Keep screenshot evidence outside the repository and record actual results in the PR."}),"\n",(0,s.jsxs)(n.p,{children:["The ",(0,s.jsx)(n.code,{children:"stand-in-project-enable"})," desktop checkpoint creates two local projects, verifies both sidebar icons are absent, enables a stand-in connected to both projects, then disables it for one project. Both icons must appear after enablement; only the disconnected project's icon must disappear after disabling."]}),"\n",(0,s.jsx)(n.p,{children:"Cover the status/history overview and secondary settings, default selection of an existing stand-in, personally owned project creation, explicit global settings navigation and return, draft retention across plugin navigation, draft cancellation, save conflicts and recovery, all-project connection with exclusions and future projects, adding roles, deterministic overlap selection, opt-in model selection, zero selection calls for a single match, assignment filtering, deduplication and legacy migration without expanding authority."})]})}function h(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},28453:(e,n,t)=>{t.d(n,{R:()=>o,x:()=>r});var i=t(96540);const s={},a=i.createContext(s);function o(e){const n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);